const {test} = require('node:test');
const assert = require('node:assert/strict');
const brand = require('../assets/brand.js');

// Captured from makeCode in the pre-rebrand application, not generated by the reader under test.
const LEGACY_CODE = 'LS-eyJ2IjoxLCJuIjoi0JDQvdGPIiwidyI6InNtYWxsIiwidCI6Mjk4MzMzMzMsInIiOjMsImQiOltbMTIsMTRdXSwicyI6WzMsM10sImciOjV9-ug30i3';

function storage(initial = {}) {
  const values = new Map(Object.entries(initial));
  return {
    get length() {return values.size;},
    key(index) {return [...values.keys()][index] ?? null;},
    getItem(key) {return values.get(key) ?? null;},
    setItem(key, value) {values.set(key, String(value));},
    removeItem(key) {values.delete(key);},
  };
}

test('migration preserves session identity, queued results, grades and unrelated storage', () => {
  const values = {
    acc: '{"kind":"s","token":"fixture-session"}', device: '0123456789abcdef',
    queue: '[{"work":"small","token":"fixture-session"}]', grades: '{"small":[{"g":5}]}',
    journal: '[{"c":"legacy-fixture"}]', theme: 'dark', name: 'Аня', works: '["small"]',
    visited: '["hooke"]', mtasks: '["hooke:0"]', task: '{"w":["small"]}', vid: 'fixture-visitor',
  };
  const state = storage(Object.fromEntries(Object.entries(values).map(([key,value]) => ['lab-sirius-' + key, value])));
  state.setItem('another-app', 'untouched');
  brand.migrateStorage(state);
  for (const [key,value] of Object.entries(values)) {
    assert.equal(state.getItem('axiora-' + key), value);
    assert.equal(state.getItem('lab-sirius-' + key), null);
  }
  assert.equal(state.getItem('another-app'), 'untouched');
});

test('newer data wins and a stale tab cannot restore an account after logout', () => {
  const state = storage({'lab-sirius-name':'old name','axiora-name':'new name'});
  brand.migrateStorage(state);
  assert.equal(state.getItem('axiora-name'), 'new name');
  state.setItem('lab-sirius-acc', 'stale-session');
  brand.migrateStorage(state);
  assert.equal(state.getItem('axiora-acc'), null);
});

test('failed writes retain original values and allow migration to resume', () => {
  const state = storage({'lab-sirius-device':'original-device'});
  const set = state.setItem;
  state.setItem = () => {throw new Error('QuotaExceededError');};
  assert.doesNotThrow(() => brand.migrate({localStorage:state}));
  assert.equal(state.getItem('lab-sirius-device'), 'original-device');
  assert.equal(state.getItem('axiora-migration-v1'), null);
  state.setItem = set;
  brand.migrateStorage(state);
  assert.equal(state.getItem('axiora-device'), 'original-device');
});

test('denied local storage does not stop the independent session migration', () => {
  const session = storage({'lab-sirius-filter':'Силы'});
  const win = {get localStorage() {throw new Error('SecurityError');}, sessionStorage:session};
  assert.doesNotThrow(() => brand.migrate(win));
  assert.equal(session.getItem('axiora-filter'), 'Силы');
});

test('previously issued result codes remain readable and checksum failures remain visible', () => {
  const result = brand.readCode(LEGACY_CODE);
  assert.equal(result.ok, true);
  assert.equal(result.o.n, 'Аня');
  assert.equal(result.o.w, 'small');
  assert.equal(result.o.v, 1);
  assert.equal(brand.readCode(LEGACY_CODE.slice(0, -1) + '0').ok, false);
});

test('new AX codes round-trip Unicode without mutating results and detect tampering', () => {
  const original = {n:'Аня 🧪', w:'small', t:123, r:[[1,2]], d:{ok:true}, s:{score:3}};
  const code = brand.makeCode(original);
  assert.match(code, /^AX-/);
  assert.deepEqual(brand.readCode(code), {o:{...original,v:2},ok:true});
  assert.equal(original.v, undefined);
  const last = code.endsWith('0') ? '1' : '0';
  assert.equal(brand.readCode(code.slice(0,-1) + last).ok, false);
  assert.equal(brand.readCode(code.replace(/^AX/, 'LS')), null);
});

test('invalid offline codes fail without throwing', () => {
  for (const code of ['',null,'AX-not-json-0','AX-W10-0','AX-bnVsbA-0','unknown']) {
    assert.equal(brand.readCode(code), null);
  }
});

test('backups from the existing server receive the new format without changing their data', () => {
  const original = {format:'lab-sirius-backup-1',teachers:[{name:'Fixture'}]};
  assert.deepEqual(brand.normalizeBackup(original), {...original,format:'axiora-backup-1'});
  assert.equal(original.format, 'lab-sirius-backup-1');
  const future = {format:'axiora-backup-2'};
  assert.equal(brand.normalizeBackup(future), future);
});
